INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(601, 'Genesis 24:23', 'Genesis', 24, 23, '&nbsp;هغۀ ووئيل، ”ما ته ووايه چې ستا پلار څوک دے، د هغۀ په کور کښې زمونږ د شپې تېرولو ځائ شته؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(602, 'Genesis 24:24', 'Genesis', 24, 24, '&nbsp;هغې جواب ورکړو، ”زما پلار بتو‌اېل دے، چې د نحور او مِلکاه زوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(603, 'Genesis 24:25', 'Genesis', 24, 25, '&nbsp;مونږ سره ډېر بوس او واښۀ شته او ستاسو د پاتې کېدو دپاره حُجره هم شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(604, 'Genesis 24:26', 'Genesis', 24, 26, '&nbsp;بيا هغه سړى خپل سر ټيټ کړو او د مالِک خُدائ عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(605, 'Genesis 24:27', 'Genesis', 24, 27, '&nbsp;هغۀ ووئيل، ”د مالِک خُدائ ثناء دې وى، چې زما د نېک اِبراهيم خُدائ پاک دے، چې هغۀ په رښتيا زما د نېک سره خپله وعده پوره کړې ده. مالِک خُدائ زما د نېک خپلوانو ته زۀ نېغ راوستلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(606, 'Genesis 24:28', 'Genesis', 24, 28, '&nbsp;جينۍ کور ته منډه کړه او خپلې مور او نورو ټولو ښځو ته يې ټوله قيصه تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(607, 'Genesis 24:29', 'Genesis', 24, 29, '&nbsp;د رِبقې يو ورور وو چې نوم يې لابن وو، هغۀ بهر د چينې طرف ته منډه کړه چې چرته د اِبراهيم نوکر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(608, 'Genesis 24:30', 'Genesis', 24, 30, '&nbsp;لابن د خپلې خور په پوزه نتکۍ او د هغې په لاسونو کَړې ليدلې وې. او رِبقې دا خبره کوله چې لابن واورېدل څۀ چې هغه سړى وئيلى وُو. هغه د اِبراهيم نوکر له ورَغلو چې هغه د خپلو اوښانو سره د چينې سره ولاړ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(609, 'Genesis 24:31', 'Genesis', 24, 31, '&nbsp;او لابن ورته ووئيل، ”ما سره کور ته لاړ شه. تۀ هغه سړے يې چې مالِک خُدائ برکت درکړے دے. تۀ دلته بهر ولې ولاړ يې؟ ما په خپل کور کښې ستا دپاره ځائ تيار کړے دے او هلته ستا د اوښانو دپاره هم ځائ شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(610, 'Genesis 24:32', 'Genesis', 24, 32, '&nbsp;نو هغه سړے دننه کور ته لاړو او لابن د اوښانو نه بارونه کوز کړل او بوس او واښۀ يې ورته واچول. بيا هغۀ د اِبراهيم د نوکر او د هغۀ د سړو دپاره اوبۀ راوړې چې خپلې پښې ووينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(611, 'Genesis 24:33', 'Genesis', 24, 33, '&nbsp;چې روټۍ يې کله راوړه، هغه سړى ووئيل، ”تر هغه پورې به زۀ خوراک نۀ کوم چې تر کومې پورې ما هغه څۀ وئيلى نۀ وى چې څۀ وئيل غواړم.“ لابن ووئيل، ”ټيک ده ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(612, 'Genesis 24:34', 'Genesis', 24, 34, '&nbsp;هغۀ خبره شروع کړه، ”زۀ د اِبراهيم نوکر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(613, 'Genesis 24:35', 'Genesis', 24, 35, '&nbsp;مالِک خُدائ زما نېک له ډېر زيات برکت ورکړے دے او هغه يې ډېر مالدار کړے دے. هغۀ له يې د ګډو او چېلو رَمې، څاروى، سپين زر، سرۀ زر، غلامان او وينځې، اوښان او خرۀ هم ورکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(614, 'Genesis 24:36', 'Genesis', 24, 36, '&nbsp;زما د نېک د ښځې ساره نه چې کله هغه بوډۍ وه د هغۀ يو زوئ وشو او زما نېک هغۀ له خپل هر څۀ ورکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(615, 'Genesis 24:37', 'Genesis', 24, 37, '&nbsp;زما نېک زما نه دا پوخ لوظ اخستے دے چې د هغۀ حُکم به منم. هغۀ وفرمائيل، د کنعان د مُلک د پېغلو نه زما زوئ له ښځه مۀ خوښوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(616, 'Genesis 24:38', 'Genesis', 24, 38, '&nbsp;خو زما د پلار خلقو، زما خپلوانو له لاړ شه او د هغۀ دپاره ښځه خوښه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(617, 'Genesis 24:39', 'Genesis', 24, 39, '&nbsp;او ما د خپل نېک نه تپوس وکړو، فرض کړه کۀ هغه ښځه زما سره نۀ راځى نو بيا؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(618, 'Genesis 24:40', 'Genesis', 24, 40, '&nbsp;هغۀ جواب راکړو چې مالِک خُدائ، چې د کوم ما همېشه فرمانبردارى کړې ده، هغه به خپله فرښته تا ته درولېږى او کاميابى به درکړى. تۀ به زما د زوئ دپاره زما د خپلو خلقو نه، زما د پلار د خاندان نه، يوه ښځه پېدا کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(619, 'Genesis 24:41', 'Genesis', 24, 41, '&nbsp;ستا دپاره صِرف يوه لار شته چې د لوظ نه آزاد شې، هغه دا چې کۀ تۀ زما خپلوانو له لاړ شې او هغوئ تا ته اِنکار وکړى، نو بيا به تۀ آزاد يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(620, 'Genesis 24:42', 'Genesis', 24, 42, '&nbsp;چې نن زۀ چينې ته راغلم، ما مالِک خُدائ ته سوال وکړو، اے مالِکه خُدايه، زما د نېک اِبراهيم خُدايه پاکه، ما له په سفر کښې کاميابى راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(621, 'Genesis 24:43', 'Genesis', 24, 43, '&nbsp;زۀ دلته د چينې سره يم، کله چې يوه جينۍ اوبو وړلو له راشى، نو زۀ به ورته ووايم چې ما له د خپل منګى نه لږې اوبۀ راکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(622, 'Genesis 24:44', 'Genesis', 24, 44, '&nbsp;کۀ هغه ما له او زما اوښانو له هم اوبۀ ورکول وغواړى، چې دا هم هغه ښځه وى چې تا زما د نېک د زوئ دپاره خوښه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(623, 'Genesis 24:45', 'Genesis', 24, 45, '&nbsp;د هغې نه مخکښې چې ما پټه په زړۀ کښې دُعا ختمه کړې وه، رِبقه چې د هغې په اوږه منګے وو راغله او لاندې چينې ته لاړه. ما هغې ته ووئيل چې، څښلو له لږې اوبۀ راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(624, 'Genesis 24:46', 'Genesis', 24, 46, '&nbsp;هغې زر د خپل ولى نه منګے راټيټ کړو او وې وئيل، اوبۀ وڅښه او زۀ به ستا اوښانو له هم اوبۀ ورکړم. نو ما هم اوبۀ وڅښلې او اوښانو له يې هم ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(625, 'Genesis 24:47', 'Genesis', 24, 47, '&nbsp;ما د هغې نه تپوس وکړو، ستا پلار څوک دے؟ نو هغې جواب راکړو، زما پلار بتو‌اېل دے چې د نحور او مِلکاه زوئ دے. بيا ما هغې له نتکۍ ورپه پوزه کړه او کَړى مې ورپه لاس کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(626, 'Genesis 24:48', 'Genesis', 24, 48, '&nbsp;ما خپل سر ټيټ کړو او د مالِک خُدائ عبادت مې وکړو. ما د مالِک خُدائ ثناء ووئيله، چې زما د نېک اِبراهيم خُدائ پاک دے، چې هغۀ زۀ نېغ زما د نېک نوسۍ له راوستلم چې هغه د اِسحاق ښځه جوړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(627, 'Genesis 24:49', 'Genesis', 24, 49, '&nbsp;نو کۀ تۀ زما د نېک سره خپله ذمه وارى پوره کول غواړې او ښۀ سلوک ورسره کوې، نو ما ته ووايه او کۀ نۀ وى نو هم ووايه، بيا به زۀ فېصله وکړم چې ما له څۀ کول په کار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(628, 'Genesis 24:50', 'Genesis', 24, 50, '&nbsp;لابن او بتو‌اېل جواب ورکړو، ”دا خبره د مالِک خُدائ نه راپېښه ده او مونږ ورته ښۀ يا بد نۀ شُو وئيلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(629, 'Genesis 24:51', 'Genesis', 24, 51, '&nbsp;دا رِبقه ده، د ځان سره يې بوځه. هغه دې ستا د نېک د زوئ ښځه شى، لکه چې څنګه مالِک خُدائ په خپله فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(630, 'Genesis 24:52', 'Genesis', 24, 52, '&nbsp;چې کله د اِبراهيم نوکر دا خبره واورېده، هغه ټيټ شو او د مالِک خُدائ عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(631, 'Genesis 24:53', 'Genesis', 24, 53, '&nbsp;بيا هغۀ ورله جامې، سپين زر او د سرو زرو کالى راوويستل او رِبقې له يې ورکړل. هغۀ د هغې ورور او مور له هم قيمتى تُحفې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(632, 'Genesis 24:54', 'Genesis', 24, 54, '&nbsp;د دې نه پس، د اِبراهيم نوکر او د هغۀ سره نورو سړو خوراک څښاک وکړو او هلته يې شپه تېره کړه. چې کله هغوئ سحر پاڅېدل، هغۀ ووئيل، ”ما خپل نېک له واپس ولېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(633, 'Genesis 24:55', 'Genesis', 24, 55, '&nbsp;خو د رِبقې ورور او د هغې مور ووئيل، ”کم از کم لسو ورځو له دې هغه زمونږ سره ايساره شى، نو بيا دې لاړه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(634, 'Genesis 24:56', 'Genesis', 24, 56, '&nbsp;خو هغۀ ووئيل، ”مونږ مۀ ايساروئ. مالِک خُدائ زما سفر کامياب کړے دے، ما خپل نېک له واپس ولېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(635, 'Genesis 24:57', 'Genesis', 24, 57, '&nbsp;هغوئ جواب ورکړو، ”مونږ به رِبقه راوغواړُو او د هغې نه به تپوس وکړُو چې هغه څۀ وائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(636, 'Genesis 24:58', 'Genesis', 24, 58, '&nbsp;نو هغوئ رِبقه راوغوښته او تپوس يې ترې وکړو، ”تۀ د دې سړى سره تلل غواړې څۀ؟“ هغې جواب ورکړو، ”آو، زۀ به لاړه شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(637, 'Genesis 24:59', 'Genesis', 24, 59, '&nbsp;نو هغوئ رِبقه او د کور مشره خِدمتګاره او نورې نوکرانې د اِبراهيم د نوکر او د هغۀ د سړو سره لېږلو ته راضى شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(638, 'Genesis 24:60', 'Genesis', 24, 60, '&nbsp;او دوئ د رِبقې دپاره برکت وغوښتلو او ورته يې ووئيل چې، ”خورې تۀ دې د زرګونو مور شې، ستا اولاد دې د خپلو دشمنانو په ښارونو بريالے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(639, 'Genesis 24:61', 'Genesis', 24, 61, '&nbsp;بيا رِبقه او د هغې نوکرانې تيارې شوې او په اوښانو سورې شوې چې د اِبراهيم د نوکر سره لاړې شى او دوئ ټول روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(640, 'Genesis 24:62', 'Genesis', 24, 62, '&nbsp;اِسحاق د بير‌لحى‌روۍ نه راغلے وو. او د کنعان صحرا کښې ايسار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(641, 'Genesis 24:63', 'Genesis', 24, 63, '&nbsp;هغه ماښام په پټو کښې چکر لګولو له ووتلو او څۀ ګورى چې اوښان راروان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(642, 'Genesis 24:64', 'Genesis', 24, 64, '&nbsp;چې کله رِبقې اِسحاق وليدلو، هغه د خپل اوښ نه کوزه شوه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(643, 'Genesis 24:65', 'Genesis', 24, 65, '&nbsp;او د اِبراهيم نوکر نه يې تپوس وکړو، ”هغه سړے چې په پټى کښې زمونږ طرف ته راروان دے څوک دے؟“ نوکر جواب ورکړو، ”هغه زما نېک دے.“ نو هغې څادر واخستلو او خپل مخ يې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(644, 'Genesis 24:66', 'Genesis', 24, 66, '&nbsp;نوکر هغه هر څۀ اِسحاق ته ووئيل چې څۀ يې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(645, 'Genesis 24:67', 'Genesis', 24, 67, '&nbsp;بيا اِسحاق رِبقه خپلې هغه خېمې ته راوستله چې د هغۀ مور ساره په کښې اوسېدلې وه او هغه يې ښځه شوه. اِسحاق د رِبقه سره مينه کوله، نو هغۀ ته د خپلې مور د مرګ نه پس آرام مِلاو شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(646, 'Genesis 25:1', 'Genesis', 25, 1, '&nbsp;بيا اِبراهيم بله ښځه وکړه، چې د هغې نوم قطوره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(647, 'Genesis 25:2', 'Genesis', 25, 2, '&nbsp;د هغې نه يې زمران، يُقسان، مِدان، ميديان، اسباق او سوخ پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(648, 'Genesis 25:3', 'Genesis', 25, 3, '&nbsp;يُقسان د شيبا او د ددان پلار وو او د ددان اولاد اسورى، لطُوسى او لومى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(649, 'Genesis 25:4', 'Genesis', 25, 4, '&nbsp;د ميديان زامن عيفه، عِفر، حنوک، ابيداع او اِلدعا وُو. دا ټول د قطوره اولاد وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(650, 'Genesis 25:5', 'Genesis', 25, 5, '&nbsp;اِبراهيم چې څۀ هم لرل هغه يې اِسحاق له ورکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(651, 'Genesis 25:6', 'Genesis', 25, 6, '&nbsp;هغۀ په خپل ژوندون کښې هغه زامنو له تُحفې ورکړې چې د هغۀ د وينځو نه پېدا شوى وُو. بيا هغۀ دا زامن د خپل زوئ اِسحاق نه لرې، د نمرخاتۀ مُلک ته ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(652, 'Genesis 25:7', 'Genesis', 25, 7, '&nbsp;چې اِبراهيم د يو سل پينځۀ اوياؤ کالو عُمر ته ورسېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(653, 'Genesis 25:8', 'Genesis', 25, 8, '&nbsp;نو اِبراهيم ساه ورکړه او ښۀ په پوخ عُمر کښې په حق ورسېدو او د ډېر عُمر سړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(654, 'Genesis 25:9', 'Genesis', 25, 9, '&nbsp;د هغۀ زامنو اِسحاق او اِسمٰعيل، د ممرۍ سره نزدې د صحر د زوئ عِفرون حِتى په پټى کښې، د مکفيله په غار کښې ښخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(655, 'Genesis 25:10', 'Genesis', 25, 10, '&nbsp;دا هغه پټے وو چې اِبراهيم د حِتيانو نه اخستے وو، اِبراهيم او د هغۀ ښځه ساره دواړه هلته ښخ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(656, 'Genesis 25:11', 'Genesis', 25, 11, '&nbsp;د اِبراهيم د مرګ نه پس، خُدائ پاک د هغۀ زوئ اِسحاق له برکت ورکړو، چې هغه بير‌لحى‌روۍ ته نزدې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(657, 'Genesis 25:12', 'Genesis', 25, 12, '&nbsp;دا د اِبراهيم د زوئ اِسمٰعيل اولاد دے، اِسمٰعيل د هاجِرې مِصرۍ زوئ وو څوک چې د ساره وينځه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
