(664, 'Genesis 25:19', 'Genesis', 25, 19, '&nbsp;دا د اِبراهيم د زوئ اِسحاق قيصه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(665, 'Genesis 25:20', 'Genesis', 25, 20, '&nbsp;اِسحاق د څلوېښتو کالو وو چې کله هغۀ د رِبقې، د بتو‌اېل لور، د لابن خور سره وادۀ وکړو. دوئ د مسوپتاميه آرامى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(666, 'Genesis 25:21', 'Genesis', 25, 21, '&nbsp;اِسحاق مالِک خُدائ ته د خپلې ښځې دپاره سوال وکړو، ځکه چې هغه شنډه وه. مالِک خُدائ د هغۀ آواز واورېدو او رِبقه اُميدواره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(667, 'Genesis 25:22', 'Genesis', 25, 22, '&nbsp;د هغې جوړه بچى پېدا کېدونکى وُو او د پېدا کېدو نه مخکښې دوئ د مور په خېټه کښې په ضد شول. نو هغې د مالِک خُدائ نه تپوس وکړو، ”په ما داسې ولې کيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(668, 'Genesis 25:23', 'Genesis', 25, 23, '&nbsp;مالِک خُدائ هغې ته وفرمائيل، ”ستا په خېټه کښې دوه قومونه دى، ستا نه دوه پېدا کېدونکى قومونه به د يو بل خِلاف وى. يو به د بل نه طاقتور وى، مشر به د کشر خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(669, 'Genesis 25:24', 'Genesis', 25, 24, '&nbsp;د هغې د بچو د پېدا کېدو وخت راغلو او د هغې جوړه زامن پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(670, 'Genesis 25:25', 'Genesis', 25, 25, '&nbsp;هغه مشر د رنګه سور وو او د هغۀ څرمن د ببرې چُوغې په شان وه، نو د هغۀ نوم يې عِيسو کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(671, 'Genesis 25:26', 'Genesis', 25, 26, '&nbsp;هغه دوېم د عِيسو پونده کلکه نيولې وه، نو د هغۀ نوم يعقوب شو. اِسحاق د شپېتو کالو وو چې دوئ پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(672, 'Genesis 25:27', 'Genesis', 25, 27, '&nbsp;هلکان لوئ شول او عِيسو يو تکړه ښکارى شو او د هغۀ بهر ګرځېدل خوښ وُو، خو يعقوب غلے سړے وو چې د کور نه به نۀ وتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(673, 'Genesis 25:28', 'Genesis', 25, 28, '&nbsp;عِيسو په اِسحاق ګران وو، ځکه چې عِيسو به کوم ځناور ښکار کړل نو اِسحاق د دې د خوړلو شوقين وو، خو په رِبقه يعقوب ګران وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(674, 'Genesis 25:29', 'Genesis', 25, 29, '&nbsp;يوه ورځ چې کله يعقوب د کُرخو ښوروا پخوله، عِيسو د ښکار نه راغلو. هغه اوږے وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(675, 'Genesis 25:30', 'Genesis', 25, 30, '&nbsp;او يعقوب ته يې ووئيل، ”زۀ د لوږې نه مرم، ما له لږه دا د سور رنګ ښوروا راکړه.“ نو ځکه د هغۀ نوم ادوم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(676, 'Genesis 25:31', 'Genesis', 25, 31, '&nbsp;يعقوب جواب ورکړو، ”زۀ به دا تا له په دې شرط درکړم کۀ تۀ ما له د خپلې مشرۍ حقُونه راکوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
