(678, 'Genesis 25:33', 'Genesis', 25, 33, '&nbsp;يعقوب جواب ورکړو، ”اول زما سره دا لوظ وکړه چې تۀ به خپل ټول حقُونه ما له راکوې.“ نو عِيسو ورسره لوظ وکړو او يعقوب ته يې خپل حقُونه ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(679, 'Genesis 25:34', 'Genesis', 25, 34, '&nbsp;بيا يعقوب هغۀ له روټۍ او څۀ ښوروا ورکړه. هغۀ خوراک څښاک وکړو او بيا پاڅېدو او لاړو. نو داسې عِيسو د خپلې مشرۍ حقُونو ته سپک وکتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(680, 'Genesis 26:1', 'Genesis', 26, 1, '&nbsp;د هغې نه وروستو، په هغه مُلک کښې يو بل قحط راغلو لکه څنګه چې مخکښې د اِبراهيم په وخت کښې راغلے وو. اِسحاق په جرار کښې، د فلستيانو بادشاه ابى‌مَلِک له ورَغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(681, 'Genesis 26:2', 'Genesis', 26, 2, '&nbsp;مالِک خُدائ اِسحاق ته راڅرګند شو او ورته يې وفرمائيل، ”مِصر ته مۀ ځه، په دې مُلک کښې اوسېږه، کوم ځائ چې زۀ درته ښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(682, 'Genesis 26:3', 'Genesis', 26, 3, '&nbsp;دلته اوسېږه او زۀ به ستا مل شم او برکت به درکړم. زۀ دا ټوله علاقه تا او ستا اولاد له درکوم. ما چې کومه وعده ستا پلار اِبراهيم سره کړې ده زۀ به هغه پوره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(683, 'Genesis 26:4', 'Genesis', 26, 4, '&nbsp;زۀ به تا له دومره ډېر اولاد درکړم لکه چې په آسمان کښې ستورى دى او زۀ به هغوئ له دا ټوله علاقه ورکړم. ټول قومونه به ستا د اولاد په وسيله برکت ومومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(684, 'Genesis 26:5', 'Genesis', 26, 5, '&nbsp;زۀ به تا له برکت درکړم، ځکه چې اِبراهيم زما تابعدارى کړې ده او زما ټول قانونونه او حُکمونه يې پوره کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(685, 'Genesis 26:6', 'Genesis', 26, 6, '&nbsp;نو اِسحاق په جرار کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(686, 'Genesis 26:7', 'Genesis', 26, 7, '&nbsp;کله چې د هغه ځائ خلقو د هغۀ د ښځې په حقله تپوس وکړو، هغۀ ووئيل چې، ”هغه زما خور ده.“ هغۀ دا اِقرار ونۀ کړو چې هغه يې ښځه ده، هغه يرېدو چې هسې نه چې خلق يې مړ کړى او رِبقه به ترې نه بوځى، ځکه چې هغه ډېره ښائسته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(687, 'Genesis 26:8', 'Genesis', 26, 8, '&nbsp;د اِسحاق هلته د ډېر وخت اوسېدو نه پس، د فلستيانو بادشاه ابى‌مَلِک د کړکۍ نه لاندې وکتل او وې ليدل چې اِسحاق خپله ښځه رِبقه راغاړه ايستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(688, 'Genesis 26:9', 'Genesis', 26, 9, '&nbsp;ابى‌مَلِک اِسحاق راوغوښتلو او ورته يې ووئيل، ”نو دا معلومه شوه چې هغه ستا ښځه ده، تا ولې وئيلى دى چې هغه ستا خور ده؟“ هغۀ جواب ورکړو، ”زما خيال دا وو چې کۀ دا مې ووئيل چې هغه زما ښځه ده نو زۀ به ووژلے شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(689, 'Genesis 26:10', 'Genesis', 26, 10, '&nbsp;ابى‌مَلِک ورته ووئيل، ”دا تا زمونږ سره څۀ کړى دى؟ زما د خلقو نه يو سړے په آسانۍ سره ستا د ښځې سره څملاستے شو او تا به مونږ ګناهګار کړى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(690, 'Genesis 26:11', 'Genesis', 26, 11, '&nbsp;ابى‌مَلِک ټولو خلقو له خبردارے ورکړو، ”کۀ څوک دې سړى يا د هغۀ ښځې له په بد نېت لاس وروړى نو خامخا به وژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(691, 'Genesis 26:12', 'Genesis', 26, 12, '&nbsp;چې کله هغه هلته اوسېدو، اِسحاق هلته زمکه وکَرله او په هغه کال يې چې څومره کَرلى وُو د هغې نه يو په سل زيات فصل يې وشو، ځکه چې مالِک خُدائ هغۀ له برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
