(693, 'Genesis 26:14', 'Genesis', 26, 14, '&nbsp;ځکه چې د هغۀ ډېر نوکران، چېلۍ او څاروى او د ګډو ډېرې رَمې وې، خو په فلستيانو هغه بد لګېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(694, 'Genesis 26:15', 'Genesis', 26, 15, '&nbsp;چې کوم کوهى د اِبراهيم په ژوند د اِبراهيم نوکرانو کنستلى وُو نو فلستيانو هغه کوهى بند کړل او د خاورو نه يې ډک کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(695, 'Genesis 26:16', 'Genesis', 26, 16, '&nbsp;ابى‌مَلِک اِسحاق ته ووئيل، ”زمونږ د مُلک نه بهر شه. تۀ زمونږ نه زيات تکړه شوے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(696, 'Genesis 26:17', 'Genesis', 26, 17, '&nbsp;نو اِسحاق لاړو او د جرار په مېدان کښې يې خېمه ولګوله، چې هلته د څۀ وخت دپاره ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
