(699, 'Genesis 26:20', 'Genesis', 26, 20, '&nbsp;د جرار شپونکى د اِسحاق د شپونکو سره په جګړه شول او وې وئيل چې، ”دا اوبۀ زمونږ دى.“ نو اِسحاق په هغه کوهى ”عِسق“ نوم کېښودو، ځکه چې هغوئ د هغۀ سره جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(700, 'Genesis 26:21', 'Genesis', 26, 21, '&nbsp;د اِسحاق نوکرانو يو بل کوهے وکنستلو او په هغې باندې هم جګړه وشوه، نو په هغې يې ”سِتنه“ نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');